IF COLUMNPROPERTY(OBJECT_ID(N'dbo.KM_Tour'), N'STT', 'IsIdentity') = 1
    SELECT v.MaKhuyenMai, v.MaTour
    FROM (VALUES
        (N'KM002', N'TOUR007'),
        (N'KM003', N'TOUR009'),
        (N'KM004', N'TOUR001'),
        (N'KM004', N'TOUR002'),
        (N'KM005', N'TOUR006'),
        (N'KM005', N'TOUR012'),
        (N'KM005', N'TOUR015'),
        (N'KM006', N'TOUR010'),
        (N'KM006', N'TOUR007'),
        (N'KM007', N'TOUR003'),
        (N'KM007', N'TOUR018'),
        (N'KM007', N'TOUR011'),
        (N'KM001', N'TOUR004'),
        (N'KM001', N'TOUR005')
    ) v(MaKhuyenMai, MaTour)
    WHERE EXISTS (SELECT 1 FROM dbo.KhuyenMai k WHERE k.MaKM = v.MaKhuyenMai)
      AND EXISTS (SELECT 1 FROM dbo.Tour t WHERE t.MaTour = v.MaTour)
      AND NOT EXISTS (
          SELECT 1 FROM dbo.KM_Tour x
          WHERE x.MaKhuyenMai = v.MaKhuyenMai AND x.MaTour = v.MaTour);
ELSE
    SELECT ISNULL((SELECT MAX(STT) FROM dbo.KM_Tour), 0)
           + ROW_NUMBER() OVER (ORDER BY v.MaKhuyenMai, v.MaTour),
           v.MaKhuyenMai, v.MaTour
    FROM (VALUES
        (N'KM002', N'TOUR007'),
        (N'KM003', N'TOUR009'),
        (N'KM004', N'TOUR001'),
        (N'KM004', N'TOUR002'),
        (N'KM005', N'TOUR006'),
        (N'KM005', N'TOUR012'),
        (N'KM005', N'TOUR015'),
        (N'KM006', N'TOUR010'),
        (N'KM006', N'TOUR007'),
        (N'KM007', N'TOUR003'),
        (N'KM007', N'TOUR018'),
        (N'KM007', N'TOUR011'),
        (N'KM001', N'TOUR004'),
        (N'KM001', N'TOUR005')
    ) v(MaKhuyenMai, MaTour)
    WHERE EXISTS (SELECT 1 FROM dbo.KhuyenMai k WHERE k.MaKM = v.MaKhuyenMai)
      AND EXISTS (SELECT 1 FROM dbo.Tour t WHERE t.MaTour = v.MaTour)
      AND NOT EXISTS (
          SELECT 1 FROM dbo.KM_Tour x
          WHERE x.MaKhuyenMai = v.MaKhuyenMai AND x.MaTour = v.MaTour);

